<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';
require_once __DIR__.'/../../includes/permissoes.php';
$tituloPagina='Agendamento de Consulta'; $codigoTela='atendimento.agendamento'; exigirPermissao($pdo,$codigoTela);
date_default_timezone_set('America/Sao_Paulo');
require_once __DIR__.'/agenda-funcoes.php';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function queryA($pdo,$sql,$args=[]){$s=$pdo->prepare($sql);$s->execute($args);return $s;}
$_SESSION['agenda_csrf']??=bin2hex(random_bytes(32));
$erro=''; $ok=$_SESSION['agenda_ok']??''; unset($_SESSION['agenda_ok']);
$dia=$_GET['dia']??date('Y-m-d'); if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$dia)) $dia=date('Y-m-d');
$medicos=$pdo->query('SELECT m.id,m.nome,e.nome especialidade FROM medicos m JOIN especialidades e ON e.id=m.especialidade_id WHERE m.ativo=1 AND e.ativa=1 ORDER BY m.nome')->fetchAll(PDO::FETCH_ASSOC);
$convenios=$pdo->query('SELECT id,nome FROM convenios WHERE ativo=1 ORDER BY nome')->fetchAll(PDO::FETCH_ASSOC);
if(isset($_GET['horarios'])){header('Content-Type: application/json');echo json_encode(horariosAgenda($pdo,(int)($_GET['medico']??0),(string)($_GET['data']??''),(int)($_GET['ignorar']??0)));exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
try{
if(!hash_equals($_SESSION['agenda_csrf'],(string)($_POST['csrf']??''))) throw new DomainException('Formulário expirado.');
$acao=$_POST['acao']??''; $id=(int)($_POST['id']??0); $pdo->beginTransaction(); $antes=null;
if($acao!=='agendar'){$antes=queryA($pdo,'SELECT * FROM agendamentos_consulta WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);if(!$antes||!in_array($antes['status'],['AGENDADO','CONFIRMADO'],true))throw new DomainException('Agendamento indisponível.');}
if(in_array($acao,['agendar','reagendar'],true)){
$horario=(string)($_POST['data_consulta']??'').'T'.(string)($_POST['hora_consulta']??'');$dt=DateTime::createFromFormat('!Y-m-d\TH:i',$horario);if(!$dt||$dt->format('Y-m-d\TH:i')!==$horario||$dt<=new DateTime()||!in_array($dt->format('i'),['00','30'],true))throw new DomainException('Escolha um horário futuro em intervalos de 30 minutos.');
$medicoAgenda=$acao==='agendar'?(int)($_POST['medico']??0):(int)$antes['medico_id'];
queryA($pdo,'SELECT id FROM medicos WHERE id=? FOR UPDATE',[$medicoAgenda]);
if(!in_array($dt->format('H:i'),horariosAgenda($pdo,$medicoAgenda,$dt->format('Y-m-d'),$id),true))throw new DomainException('Horário indisponível na agenda médica.');
$horario=$dt->format('Y-m-d H:i:s');
if($acao==='agendar'){$p=(int)($_POST['paciente']??0);$m=(int)($_POST['medico']??0);$c=(int)($_POST['convenio']??0);$tipo=$_POST['tipo']??'';if(!queryA($pdo,'SELECT id FROM pacientes WHERE id=?',[$p])->fetchColumn()||!in_array($m,array_map('intval',array_column($medicos,'id')),true)||!in_array($c,array_map('intval',array_column($convenios,'id')),true)||!in_array($tipo,['PRIMEIRA','RETORNO'],true))throw new DomainException('Confira paciente, médico, convênio e tipo.');queryA($pdo,'INSERT INTO agendamentos_consulta (paciente_id,medico_id,convenio_id,horario,tipo) VALUES (?,?,?,?,?)',[$p,$m,$c,$horario,$tipo]);$id=(int)$pdo->lastInsertId();}
else queryA($pdo,"UPDATE agendamentos_consulta SET horario=?,status='AGENDADO' WHERE id=?",[$horario,$id]);
}elseif(in_array($acao,['confirmar','cancelar','falta'],true)){if($acao==='falta'&&strtotime($antes['horario'])>time())throw new DomainException('Horário ainda não ocorreu.');$status=['confirmar'=>'CONFIRMADO','cancelar'=>'CANCELADO','falta'=>'FALTOU'][$acao];queryA($pdo,'UPDATE agendamentos_consulta SET status=? WHERE id=?',[$status,$id]);}
elseif($acao==='iniciar'){
if(substr($antes['horario'],0,10)!==date('Y-m-d')||$antes['status']!=='CONFIRMADO')throw new DomainException('Confirme a consulta e inicie somente no dia agendado.');
$m=queryA($pdo,'SELECT m.nome,e.nome especialidade FROM medicos m JOIN especialidades e ON e.id=m.especialidade_id WHERE m.id=? AND m.ativo=1 AND e.ativa=1',[$antes['medico_id']])->fetch(PDO::FETCH_ASSOC);$c=queryA($pdo,'SELECT nome FROM convenios WHERE id=? AND ativo=1',[$antes['convenio_id']])->fetchColumn();if(!$m||!$c||mb_strlen($c)>100||mb_strlen($m['especialidade'])>100)throw new DomainException('Confira os cadastros ativos.');
queryA($pdo,"INSERT INTO atendimentos (numero_atendimento,paciente_id,origem,tipo_atendimento,convenio,especialidade,profissional_id,profissional_responsavel,status) VALUES (?,?,'AMBULATORIO','AMBULATORIO',?,?,?,?,'AGUARDANDO_MEDICO')",['TMP-'.bin2hex(random_bytes(8)),$antes['paciente_id'],$c,$m['especialidade'],$antes['medico_id'],$m['nome']]);$at=(int)$pdo->lastInsertId();queryA($pdo,'UPDATE atendimentos SET numero_atendimento=? WHERE id=?',['AT'.str_pad((string)$at,6,'0',STR_PAD_LEFT),$at]);queryA($pdo,'INSERT INTO contas_hospitalares (atendimento_id,paciente_id,convenio_id) VALUES (?,?,?)',[$at,$antes['paciente_id'],$antes['convenio_id']]);queryA($pdo,"UPDATE agendamentos_consulta SET atendimento_id=?,status='EM_ATENDIMENTO' WHERE id=?",[$at,$id]);
}else throw new DomainException('Operação inválida.');
$novo=queryA($pdo,'SELECT * FROM agendamentos_consulta WHERE id=?',[$id])->fetch(PDO::FETCH_ASSOC);
queryA($pdo,"INSERT INTO auditoria_sistema (usuario_id,acao,modulo,tela,entidade,registro_id,descricao,ip,metodo_http,url,dados_anteriores,dados_novos) VALUES (?,'AGENDA_CONSULTA','Atendimento','Agendamento de Consulta','agendamentos_consulta',?,?,?,'POST',?,?,?)",[(int)$_SESSION['usuario_id'],(string)$id,$acao,$_SERVER['REMOTE_ADDR']??null,$_SERVER['SCRIPT_NAME'],json_encode($antes,JSON_THROW_ON_ERROR),json_encode($novo,JSON_THROW_ON_ERROR)]);
$pdo->commit();$_SESSION['agenda_ok']='Operação realizada com sucesso.';header('Location: agendamento-consulta.php?dia='.urlencode(substr($novo['horario'],0,10)));exit;
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$erro=$e instanceof DomainException?$e->getMessage():($e instanceof PDOException&&($e->errorInfo[1]??0)==1062?'Horário já reservado para o médico ou paciente.':'Não foi possível concluir a operação.');if(!($e instanceof DomainException))error_log($e->getMessage());}}
$q=trim($_GET['q']??'');$pacientes=$q===''?[]:queryA($pdo,'SELECT id,nome,cpf FROM pacientes WHERE cpf=? OR nome LIKE ? ORDER BY nome LIMIT 50',[preg_replace('/\D/','',$q),'%'.$q.'%'])->fetchAll(PDO::FETCH_ASSOC);
$lista=queryA($pdo,'SELECT a.*,p.nome paciente,m.nome medico,e.nome especialidade,t.numero_atendimento,t.status status_atendimento FROM agendamentos_consulta a JOIN pacientes p ON p.id=a.paciente_id JOIN medicos m ON m.id=a.medico_id JOIN especialidades e ON e.id=m.especialidade_id LEFT JOIN atendimentos t ON t.id=a.atendimento_id WHERE DATE(a.horario)=? ORDER BY a.horario',[$dia])->fetchAll(PDO::FETCH_ASSOC);
require __DIR__.'/../../includes/header.php';require __DIR__.'/../../includes/sidebar.php';
?>
