<?php if($q!==''&&!$pacientes):?><p>Nenhum paciente encontrado.</p><?php endif;if($pacientes):?><form method="post" class="form-card"><input type="hidden" name="csrf" value="<?=h($_SESSION['agenda_csrf'])?>"><input type="hidden" name="acao" value="agendar"><div class="card-title"><div class="card-title-icon"><i class="fa-solid fa-calendar-plus"></i></div><div><span>Novo agendamento</span><h3>Dados da consulta</h3></div></div><div class="form-grid"><div class="form-field"><label>Paciente</label><select name="paciente" required><?php foreach($pacientes as $p):?><option value="<?=$p['id']?>"><?=h($p['nome'].' — '.$p['cpf'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Médico e especialidade</label><select name="medico" required><?php foreach($medicos as $m):?><option value="<?=$m['id']?>"><?=h($m['nome'].' — '.$m['especialidade'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Convênio</label><select name="convenio" required><?php foreach($convenios as $c):?><option value="<?=$c['id']?>"><?=h($c['nome'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Data da consulta</label><input type="date" name="data_consulta" required></div><div class="form-field"><label>Horário disponível</label><select name="hora_consulta" required><option value="">Selecione médico e data</option></select></div><div class="form-field"><label>Tipo</label><select name="tipo"><option value="PRIMEIRA">Primeira consulta</option><option value="RETORNO">Retorno</option></select></div></div><div class="form-actions"><button class="create-attendance-button">Agendar consulta</button></div></form><?php endif;?>
<section class="form-card"><div class="card-title"><div class="card-title-icon"><i class="fa-solid fa-calendar-days"></i></div><div><span>Agenda médica</span><h3>Consultas do dia</h3></div></div><form method="get" class="row"><div class="form-field"><label>Data</label><input type="date" name="dia" value="<?=h($dia)?>" required></div><button class="create-attendance-button">Consultar</button></form><?php if(!$lista):?><p>Nenhuma consulta nesta data.</p><?php endif;foreach($lista as $a):?><div class="item"><strong><?=h(substr($a['horario'],11,5).' — '.$a['paciente'])?></strong> <span class="badge"><?=h(in_array($a['status_atendimento'],['ALTA','FINALIZADO'],true)?'REALIZADO':$a['status'])?></span><p><?=h($a['medico'].' — '.$a['especialidade'].' | '.$a['tipo'].' '.($a['numero_atendimento']??''))?></p><?php if(in_array($a['status'],['AGENDADO','CONFIRMADO'],true)):?><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=h($_SESSION['agenda_csrf'])?>"><input type="hidden" name="id" value="<?=$a['id']?>"><button name="acao" value="confirmar">Confirmar</button><button name="acao" value="cancelar" onclick="return confirm('Cancelar consulta?')">Cancelar</button><button name="acao" value="falta">Faltou</button><?php if($a['status']==='CONFIRMADO'&&$dia===date('Y-m-d')):?><button name="acao" value="iniciar">Iniciar atendimento</button><?php endif;?><input type="hidden" name="medico" value="<?=$a['medico_id']?>"><input type="date" name="data_consulta" aria-label="Nova data"><select name="hora_consulta" aria-label="Novo horário"><option value="">Selecione a data</option></select><button name="acao" value="reagendar">Reagendar</button></form><?php endif;?></div><?php endforeach;?></section></section></main></div><script>document.querySelectorAll('form').forEach(f=>{const d=f.elements.data_consulta,m=f.elements.medico,h=f.elements.hora_consulta;if(!d||!m||!h)return;let seq=0;async function load(){const n=++seq;h.replaceChildren(new Option('Carregando...',''));if(!d.value||!m.value){h.replaceChildren(new Option('Selecione médico e data',''));return;}try{const r=await fetch('agendamento-consulta.php?'+new URLSearchParams({horarios:1,medico:m.value,data:d.value,ignorar:f.elements.id?.value||0}));if(!r.ok)throw Error();const a=await r.json();if(n!==seq)return;h.replaceChildren(new Option(a.length?'Selecione o horário':'Sem horários disponíveis',''));a.forEach(x=>h.add(new Option(x,x)));}catch(e){if(n===seq)h.replaceChildren(new Option('Erro ao consultar horários',''));}}d.addEventListener('change',load);m.addEventListener('change',load);});</script><?php require __DIR__.'/../../includes/footer.php';?>
